import java.util.*;import java.util.concurrent.atomic.*;import java.io.*;
/** Actual original Batch run/emit/rescue/completion/receipt bodies with retained terminal objects. */
public final class SourceBatchTerminalPlan {
 static int cases,batches,receipts,outputs,completions,frames,failures;static void check(boolean b,String s){if(!b)throw new AssertionError(s);cases++;}static void put(Object o,String k,Object v){try{SourceSignedRecoveryPlan.set(o,k,v);}catch(Exception e){throw new AssertionError(e);}}
 @SuppressWarnings("unchecked")static List<Object> list(Object batch,String key){return (List<Object>)CombatAccess.field(batch,key);}
 static void clean(Object batch){check(list(batch,"outputs").isEmpty()&&list(batch,"completions").isEmpty(),"terminal Batch releases output/closure lists even while caller retains Batch");for(String key:List.of("target","targetBinding","material","targetReceipt"))check(CombatAccess.field(batch,key)==null,"terminal mutable payload cleared "+key);}
 static void register(Object batch,ClientSession pc,NativeSelfCastAction.Task body,NativeLightAction.Completion first,NativeLightAction.Completion second)throws Exception{var local=SourceNpcHpOutputPlan.batches();var old=local.get();var lock=pc.nativePlayerActionLock();lock.lock();try{local.set(batch);NativeLightAction.deferScoped(body);NativeLightAction.finishScoped(first);NativeLightAction.finishScoped(second);}finally{lock.unlock();if(old==null)local.remove();else local.set(old);}}
 static void original(String scenario)throws Exception{var f=SourceControlledAudiencePlan.fixture(BattleCompanion.Kind.SUMMON,false);var b=f.base();Object batch=SourceNpcHpOutputPlan.batch(b.caster());put(batch,"target",b.target());put(batch,"targetBinding",NativePlayerCommit.Binding.capture(b.target()));var events=new ArrayList<String>();var published=new ArrayList<Boolean>();var seenFailure=new ArrayList<Throwable>();var io=new IOException("detached Batch IO");var runtime=new IllegalStateException("detached Batch body");var error=new AssertionError("detached Batch body Error");var callback=new IllegalStateException("detached completion");var socket=SourceNpcHpOutputPlan.io(b.observer());var packet=Protocol.effectObject(777,44);
  register(batch,b.caster(),()->{outputs++;events.add("output");switch(scenario){case "io","io-completion"->throw io;case "runtime"->throw runtime;case "error"->throw error;default->{var local=NativeAreaMaterialAction.current;var old=local.get();local.set(f.c());var out=new NativeSourceControlledDisplay.Output(b.observer(),f.c().bindings.get(b.observer()),packet,"detached original Batch",f.target(),false,NativeSourceControlledAudience.first(f.action(),b.observer(),f.c().bindings.get(b.observer())));f.action().outbound=out;try{b.observer().nativeSelfOriginalSend(packet,"detached Batch final cipher");frames++;}finally{f.action().outbound=null;if(old==null)local.remove();else local.set(old);}}}},(ok,why)->{events.add("close");published.add(ok);seenFailure.add(why);check(!list(batch,"outputs").isEmpty()&&list(batch,"completions").size()==2&&CombatAccess.field(batch,"target")==b.target(),"original callbacks see original pending payload before terminal cleanup");f.action().close();completions++;if(scenario.equals("completion")||scenario.equals("io-completion"))throw callback;},(ok,why)->{events.add("second");published.add(ok);seenFailure.add(why);completions++;});
  var rescue=new NativeSourceCubeVisibility.Work(null,b.observer(),f.c().bindings.get(b.observer()),packet,"detached invalid independent cube work",false,false);list(batch,"outputs").add(rescue);if(scenario.equals("caster-role"))put(b.caster(),"selectedCharacter","retired-batch-caster");if(scenario.equals("target-role"))put(b.target(),"selectedCharacter","retired-batch-target");Throwable caught=null;try{((Runnable)batch).run();}catch(Throwable failure){caught=failure;}batches++;check(events.get(events.size()-2).equals("close")&&events.get(events.size()-1).equals("second")&&published.size()==2,"original completion order runs every completion before cleanup");boolean rejected=scenario.equals("caster-role")||scenario.equals("target-role");boolean failed=Set.of("io","io-completion","runtime","error").contains(scenario);check(published.stream().allMatch(v->v==(!rejected&&!failed)),"original publication success/failure policy retained "+scenario);check(f.action().closed&&f.action().targets.isEmpty()&&f.c().nativeSourceControlledAction==null&&rescue.claimed.get(),"original Action close and independent cube rescue happen before reference release");
  if(scenario.startsWith("io")){check(caught instanceof UncheckedIOException u&&u.getCause()==io&&seenFailure.stream().allMatch(x->x==io),"original IOException wrapping/callback cause retained");if(scenario.equals("io-completion"))check(Arrays.asList(io.getSuppressed()).contains(callback),"original IO remains primary over completion failure");failures++;}else if(scenario.equals("runtime")){check(caught==runtime&&seenFailure.stream().allMatch(x->x==runtime),"original RuntimeException identity retained");failures++;}else if(scenario.equals("error")){check(caught==error&&seenFailure.stream().allMatch(x->x==error),"original Error identity retained");failures++;}else if(scenario.equals("completion")){check(caught==callback&&seenFailure.stream().allMatch(Objects::isNull),"original completion failure identity retained after published output");failures++;}else check(caught==null&&seenFailure.stream().allMatch(Objects::isNull),"normal or original early rejection has no new failure");check(socket.bytes.size()==(!rejected&&!failed?packet.length+2:0),"actual final cipher matches original publication result "+scenario);clean(batch);int before=events.size();((Runnable)batch).run();check(events.size()==before&&rescue.claimed.get(),"retained terminal Batch cannot replay callbacks or sent output");clean(batch);
 }
 static void receipt()throws Exception{var f=SourceControlledAudiencePlan.fixture(BattleCompanion.Kind.PET,true);var b=f.base();put(b.life(),"nativeSummonRetirements",java.util.concurrent.ConcurrentHashMap.newKeySet());put(b.caster(),"sourceItemAdmissionGate",new Object());put(b.target(),"sourceItemAdmissionGate",new Object());var batchesLocal=SourceNpcHpOutputPlan.batches();var held=new AtomicReference<Object>();var receiptRef=new AtomicReference<Object>();var closed=new AtomicInteger();byte[] packet=Protocol.effectObject(777,44);var socket=SourceNpcHpOutputPlan.io(b.observer());var local=NativeAreaMaterialAction.current;var old=local.get();local.set(f.c());long pending=NativePlayerVitalCompletions.pending(b.life());try{NativeSourcePlayerActionLock.run(b.viewer(),()->{try{NativeLightAction.commitPair(b.caster(),b.target(),()->{Object batch=batchesLocal.get();held.set(batch);NativeSourceControlledDisplay.queue(f.action(),b.observer(),packet,"receipt-delayed actual controlled output",f.target(),false);NativeLightAction.finishScoped((ok,why)->{check(ok&&why==null&&!b.caster().nativePlayerActionLock().isHeldByCurrentThread()&&!b.target().nativePlayerActionLock().isHeldByCurrentThread()&&!b.viewer().nativePlayerActionLock().isHeldByCurrentThread(),"actual target receipt completion waits for all original locks");f.action().close();closed.incrementAndGet();completions++;});});}catch(IOException e){throw new UncheckedIOException(e);}Object batch=held.get();check(batch!=null&&!list(batch,"outputs").isEmpty()&&!list(batch,"completions").isEmpty()&&!f.action().closed&&closed.get()==0&&socket.bytes.size()==0,"receipt-pending Batch retains unsent outputs/completions and live Action");receiptRef.set(CombatAccess.field(batch,"targetReceipt"));check(receiptRef.get()!=null&&NativePlayerVitalCompletions.pending(b.life())>pending,"actual original target receipt remains pending until third actor unlock");});}finally{if(old==null)local.remove();else local.set(old);}check(closed.get()==1&&f.action().closed&&socket.bytes.size()==packet.length+2&&NativePlayerVitalCompletions.pending(b.life())==pending,"actual receipt publishes exactly once and releases original pending count");check(((java.util.concurrent.atomic.AtomicBoolean)CombatAccess.field(receiptRef.get(),"released")).get(),"original receipt released after actual emit despite cleared Batch link");clean(held.get());receipts++;batches++;frames++;}
 static final class Payload {List<Object> outputs,completions;Object target=new Object(),targetBinding=new Object(),material=new Object(),targetReceipt=new Object();}
 static void cleanupFailures()throws Throwable{for(boolean hasPrimary:List.of(false,true)){var p=new Payload();var first=new IllegalStateException("first terminal cleanup");var second=new IllegalArgumentException("second terminal cleanup");var primary=new AssertionError("original emitter remains primary");p.outputs=new ArrayList<>(){public void clear(){throw first;}};p.completions=new ArrayList<>(){public void clear(){throw second;}};Throwable caught=null;try{NativeSourceBatchTerminal.finish(p,hasPrimary?primary:null);}catch(Throwable e){caught=e;}check(hasPrimary?caught==null&&Arrays.asList(primary.getSuppressed()).equals(List.of(first,second)):caught==first&&Arrays.asList(first.getSuppressed()).equals(List.of(second)),"cleanup preserves original primary or first cleanup failure and suppression order");check(p.target==null&&p.targetBinding==null&&p.material==null&&p.targetReceipt==null,"later mutable payloads clear even when either list cleanup fails");}check(NativeSourceBatchTerminal.class.getDeclaredFields().length==0,"no global roots/TLS/queue/worker added");}
 public static void main(String[]args)throws Throwable{var area=NativeAreaMaterialAction.current;var oldArea=area.get();var frame=SourceNpcHpOutputPlan.frames();var oldFrame=frame.get();var light=SourceNpcHpOutputPlan.batches();var oldBatch=light.get();var rules=CombatRules.class.getDeclaredField("current");rules.setAccessible(true);var oldRules=rules.get(null);var controls=NativeSourceOtherControls.class.getDeclaredField("current");controls.setAccessible(true);var oldControls=controls.get(null);try{area.remove();frame.remove();light.remove();var path=java.nio.file.Path.of("detached-original-Batch-terminal-no-Source-reader");rules.set(null,new CombatRules.Snapshot(Map.of(),path,path,path,Set.of(),path));var props=new Properties();props.setProperty("hpbar","true");controls.set(null,new NativeSourceOtherControls.Snapshot(NativeSourceDisplayPlan.Settings.read(props),path));for(String scenario:List.of("normal","io","runtime","error","completion","io-completion","caster-role","target-role"))original(scenario);receipt();cleanupFailures();check(batches==9&&receipts==1&&outputs==6&&completions==17&&frames==3&&failures==5,"original terminal branches, real delayed receipt, output/exception/cleanup counters");}finally{if(oldArea==null)area.remove();else area.set(oldArea);if(oldFrame==null)frame.remove();else frame.set(oldFrame);if(oldBatch==null)light.remove();else light.set(oldBatch);rules.set(null,oldRules);controls.set(null,oldControls);}check(area.get()==oldArea&&frame.get()==oldFrame&&light.get()==oldBatch&&rules.get(null)==oldRules,"all original TLS/rules/controls restored");System.out.println("PASS"+cases+" Batch terminal original-run/emit/rescue/completion/receipt contracts; original-batches="+batches+", delayed-receipts="+receipts+", output-bodies="+outputs+", completions="+completions+", memory-frames="+frames+", original-failure-cases="+failures+"; full earlier cast/HP/role/Main/Source/backend/memory/game/MySQL remain open");}
}
